import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedbackForm, setFeedbackForm] = useState({
    questions: [
      {
        id: 1,
        text: 'How would you rate the tutorial?',
        type: 'rating',
        options: ['1', '2', '3', '4', '5']
      },
      {
        id: 2,
        text: 'What did you find most useful in the tutorial?',
        type: 'text'
      }
    ]
  });

  const handleFormChange = (id, value) => {
    setFeedbackForm((prevForm) => {
      const newForm = { ...prevForm };
      newForm.questions.forEach((question) => {
        if (question.id === id) {
          question.value = value;
        }
      });
      return newForm;
    });
  };

  return (
    <FeedbackContext.Provider value={{ feedbackForm, handleFormChange }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackContext, FeedbackProvider };
```
